CREATE TABLE wallet (
    user_id  VARCHAR(10) PRIMARY KEY,
    balance  INTEGER NOT NULL CHECK (balance >= 0)
);
INSERT INTO wallet VALUES ('riya', 2000), ('kabir', 1000);

BEGIN;
UPDATE wallet SET balance = balance - 500 WHERE user_id = 'riya';
UPDATE wallet SET balance = balance + 500 WHERE user_id = 'kabir';
COMMIT;

SELECT SUM(balance) FROM wallet;   -- 3000, transfer se pehle bhi 3000

