CREATE TABLE customer (
    cust_id   INT PRIMARY KEY,
    name      VARCHAR(40) NOT NULL,
    city      VARCHAR(30),          -- composite address flatten hua
    pin       CHAR(6)
);
CREATE TABLE customer_phone (       -- multivalued attribute
    cust_id   INT REFERENCES customer(cust_id),
    phone     VARCHAR(15),
    PRIMARY KEY (cust_id, phone)
);
CREATE TABLE restaurant (
    rest_id   INT PRIMARY KEY,
    name      VARCHAR(40) NOT NULL
);
CREATE TABLE menu_item (            -- weak entity, owner = restaurant
    rest_id   INT REFERENCES restaurant(rest_id) ON DELETE CASCADE,
    item_no   INT,                  -- discriminator
    dish      VARCHAR(40),
    price     DECIMAL(8,2),
    PRIMARY KEY (rest_id, item_no)
);
CREATE TABLE orders (               -- N:1 se customer, total participation
    order_id  INT PRIMARY KEY,
    cust_id   INT NOT NULL REFERENCES customer(cust_id),
    placed_at TIMESTAMP
);
CREATE TABLE order_item (           -- M:N orders-menu_item, attribute qty
    order_id  INT REFERENCES orders(order_id),
    rest_id   INT,
    item_no   INT,
    qty       INT CHECK (qty > 0),
    PRIMARY KEY (order_id, rest_id, item_no),
    FOREIGN KEY (rest_id, item_no) REFERENCES menu_item(rest_id, item_no)
);
